WFJ.Data.add("gossip", {
  ["37036f196ac5248d"] = { "Allora è con grande orgoglio che ti dico che Brakgul Deathbringer ti attende nella Hall of Arms, pronto ad aiutarti a raggiungere la ⟦Warsong Gulch=Forra dei Cantaguerra⟧. Cercalo nella ⟦Valley of Honor=Valle dell'Onore⟧.", "." },
  ["37039c9716d114d8"] = { "Horgus mi ha divorato! Sento ancora i suoi denti su di me!", "." },
  ["37064cccbbe116f9"] = { "Non ho tempo da perdere, {class}; c'è una guerra da preparare ad ⟦Ahn'Qiraj=Ahn'qiraj⟧. Se vuoi aiutare, stiamo raccogliendo Pietre del Nucleo Carbonizzate dal ⟦Molten Core=Nucleo Ardente⟧. Me ne servono $2110w in tutto, e al momento ne ho $2109w.", "." },
  ["3711289e31ed9e78"] = { "Per troppo tempo ho atteso inerte, in preda a questa nebbia... a questo malessere, a piangere ciò che sarebbe potuto essere... ciò che sarebbe dovuto essere.", "." },
  ["3716bf22d03c0c43"] = { "Vorrei fare un acquisto, Nipsy.", "." },
  ["37180c0564d2a324"] = { "Obsidion, sorgi e servi il tuo padrone!", "." },
  ["371abcc187f442f6"] = { "Vedo l'uscita! Presto, presto!", "." },
  ["371d7988608d34ff"] = { "Oh oh! Io me la filo!", "." },
  ["3720408ad864ac2d"] = { "Dimmi di più su questi ippogrifi.", "." },
  ["3733c2395899e857"] = { "Chi osa disturbare la mia meditazione?", "." },
  ["373814e9bca34b13"] = { "SCAPPARE! SCAPPARE SU COLLINE!", "." },
  ["373c11fe7bd9a723"] = { "Scendi subito da lì! Non voglio che ti arrampichi su quel coso. Non è sicuro.", "." },
  ["373ee341c4e64826"] = { "Venite a prendere il pane fresco!", "." },
  ["37403fa69a78325e"] = { "⟦Warsong Gulch=Forra dei Cantaguerra⟧", "." },
  ["3743095dd5fd0cb0"] = { "Non riesco a gestire questo {name} senza aiuto! Aiuto!", "." },
  ["37455bce1587b1c1"] = { "Non affannarti con le faccende del passato, {name}!", "." },
  ["3748421288575130"] = { "Oh, vuoi imparare a raccogliere margheritine, eh? Ah! Ti sto solo prendendo in giro, <ragazzo/ragazza>.\n\nÈ una bella professione, e Reyna Stonebranch può mostrarti come si fa. Lavora all'Ironforge Physician, sul lato sud della ⟦Great Forge=Grande Forgia⟧, qui a ⟦Ironforge=Forgiardente⟧.", "." },
  ["3748e7eff91aa172"] = { "Abbattimi pure. Rinascerò... Ancora più potente...", "." },
  ["3749939196177aff"] = { "Scoprire di più su queste creature non è stato facile. Il mio amico e la persona che ha assoldato i suoi mercenari per rubare il libro degli incantesimi di lord Valthalak sono entrambi dati per morti da un po'.", "." },
  ["375141b873fad742"] = { "Nessuno dei due generali è stato generato.", "." },
  ["3754a3f5a21c1b3c"] = { "Va bene, resta vicino. Questi demoni ti salteranno addosso dall'ombra se abbassi la guardia.", "." },
  ["3759afdda241ba5b"] = { "I Kolkar regneranno!", "." },
  ["3759fb74a489bda2"] = { "Che sollievo essere fuori da quella trincea maledetta. Anche se quassù non è molto meglio!", "." },
  ["3760c4cd6598ccb5"] = { "Mi serve una fiala di ⟦Aqual Quintessence=Quintessenza Acquea⟧, Idraxis: vado nel ⟦Molten Core=Nucleo Ardente⟧ a spegnere una runa dei Signori del Fuoco", "." },
  ["37631c03eccbd320"] = { "Proviamo...", "." },
  ["376e05195608074a"] = { "Salute, {name}. Sono il duca Nicholas Zverenhoff dell'⟦Argent Dawn=Alba d'Argento⟧.", "." },
  ["376fb935c2dbf56f"] = { "%s ride della tua richiesta sciocca.", "." },
  ["37778718459e0403"] = { "È un onore conoscerti, {name}, ma la tua abilità con le pozioni è superiore alla mia. Va' dal dottor Herbert Halsey, un non morto che si trova nell'Apothecarium di ⟦Undercity=Sepulcra⟧. D'ora in poi potrà aiutarti lui.", "." },
  ["378df593e699295d"] = { "Dov'è l'istruttore di pesca?", "." },
  ["379568f81c5d65ac"] = { "Non fraintendermi, preferirei non stare giorno dopo giorno in un tunnel pieno di silitidi, ma se nascondermi qui a osservare i movimenti di queste creature ci aiuterà a vincere la guerra, allora lo farò per tutto il tempo necessario.", "." },
  ["37979c6abee80670"] = { "Basta chiacchiere. Che vengano pure. Ridurremo le loro ossa in polvere.", "." },
  ["37aa2264b4a9c10d"] = { "Non dimenticare i sacrifici compiuti in questo giorno, elfo della notte. Abbiamo tutti sofferto immensamente per mano di queste bestie.", "." },
  ["37af0b57b68b1399"] = { "Il mio piano d'affari non prevedeva di dover ospitare kodo giganti... forse avrei dovuto mettermi nel ramo dei cestini intrecciati sott'acqua.", "." },
  ["37c49ad5514c16fd"] = { "Ora, dove ho messo quel fossile misterioso? Ah, forse lassù...", "." },
  ["37ce0dc9338559a5"] = { "Ehm... li ho trovati così. Volevo mostrare al re che erano una minaccia! Senti, capitano... ho sentito la guardia Fengus chiamarti grassone inutile e amico degli gnoll!", "." },
  ["37d8f81062bf0933"] = { "Entra, entra. Solo non sederti troppo vicino alla stufa. Oggi non è ancora esplosa, ma per sicurezza credo sia meglio che ti sieda da un'altra parte.", "." },
  ["37dfda37d3572213"] = { "È semplicemente orribile. I nostri tre migliori piloti sono stati abbattuti sopra il territorio dell'⟦Alliance=Alleanza⟧ durante un assalto aereo. Nessuno sa se siano vivi o morti!\n\nÈ un colpo terribile per la nostra capacità di attacco aereo.", "." },
  ["37e2362cba10b20d"] = { "%s ha raggiunto le sue piene dimensioni!", "." },
  ["37e5e8656c4ab552"] = { "Calma, gente. Faremo la nostra incursione molto presto.", "." },
  ["37e863ec05ac3f9c"] = { "%s lancia in aria della dinamite, che atterra lì vicino.", "." },
  ["37eab42a3d1185dd"] = { "<Guarda nella lacrima cristallina.>", "." },
  ["37f5c7488a7e4841"] = { "Non credo che una carica basterà. Continua a tenerli a bada!", "." },
  ["37f653eef9d81cb1"] = { "Dove posso trovare il Torio Incantato?", "." },
  ["37f987c2d6c19bd6"] = { "La paura alberga nel tuo cuore, {name}. Quando sarai davvero <pronto/pronta> ad affrontare Vorsha the Lasher, vieni a parlarmi.", "." },
  ["37fb6a7f5227325c"] = { "Bella domanda, {class}. Stando alle ultime notizie, abbiamo raccolto $1997w lingotti di rame sui $1998w necessari. Inoltre mi dicono che abbiamo $2002w lingotti di ferro su $2003w, e $2011w lingotti di torio sui $2012w richiesti.", "." },
})
